3	import { OpenServiceValidationError } from '../../server-errors.ts';
4	import type { AnySchema } from './types.ts';
5	import type { ValidationMeta } from './errors.ts';
6	
7	/**
8	 * Re-throws asynchronous subscription failures on the microtask queue so they are not silently
9	 * swallowed by promise chains started from reactive listeners.
10	 */
11	export function rethrowAsync(error: unknown): void {
12	  queueMicrotask(() => {
13	    throw error;
14	  });
15	}
16	
17	/**
18	 * Validates a value with a Standard Schema and returns the parsed output value.
19	 *
20	 * Any schema issues are wrapped in `OpenServiceValidationError`, which standardizes the operation
21	 * metadata while preserving the schema's own expectation text for the actionable details.
22	 */
23	export async function validateSchema<TSchema extends AnySchema>(
24	  schema: TSchema,
25	  value: unknown,
26	  meta: Omit<ValidationMeta, 'issues'>
27	): Promise<StandardSchemaV1.InferOutput<TSchema>> {
28	  const validationResult = await schema['~standard'].validate(value);
29	
30	  if (validationResult.issues) {
31	    throw new OpenServiceValidationError({ ...meta, issues: validationResult.issues });
32	  }
33	
34	  return validationResult.value;
35	}
